const crypto=require('crypto');const{Pool}=require('pg');const pool=new Pool({connectionString:process.env.DATABASE_URL,max:2,ssl:{rejectUnauthorized:false}});const ISS='https://anthares-ara-mcp.anthares1.workers.dev';function out(r,s,b){r.status(s).json(b)}function safe(a,b){const x=Buffer.from(String(a)),y=Buffer.from(String(b));return x.length===y.length&&crypto.timingSafeEqual(x,y)}async function pub(){const r=await fetch(ISS+'/.well-known/ara-control-key',{headers:{'cache-control':'no-cache'}});if(!r.ok)throw Error('key_unavailable');return r.text()}function path(route){return route==='status'?'/v1/mcp/oauth/bootstrap-status':'/v1/mcp/oauth/bootstrap-verify'}function raw(req){return req.method==='GET'||req.method==='HEAD'?'':(typeof req.body==='string'?req.body:JSON.stringify(req.body||{}))}async function auth(req,route){if(String(req.headers['x-ara-signer']||'')!=='anthares-remote-mcp')return false;const ts=String(req.headers['x-ara-timestamp']||''),sig=String(req.headers['x-ara-signature']||''),n=Number(ts);if(!n||Math.abs(Date.now()-n)>30000||!sig)return false;const msg=Buffer.from(ts+'\n'+String(req.method).toUpperCase()+'\n'+path(route)+'\n'+raw(req));try{return crypto.verify(null,msg,await pub(),Buffer.from(sig,'base64url'))}catch{return false}}async function table(){await pool.query('CREATE TABLE IF NOT EXISTS ara_oauth_consumed(kind text NOT NULL,issuer text NOT NULL,jti text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(kind,issuer,jti))')}async function active(){const h=String(process.env.ARA_BOOTSTRAP_OTP_HASH||''),exp=Number(process.env.ARA_BOOTSTRAP_OTP_EXP||0);if(!/^[0-9a-f]{64}$/i.test(h)||exp<=Math.floor(Date.now()/1000))return false;await table();const q=await pool.query('SELECT 1 FROM ara_oauth_consumed WHERE kind=$1 AND issuer=$2 AND jti=$3 LIMIT 1',['bootstrap_otp',ISS,h]);return q.rowCount===0}module.exports=async(req,res)=>{try{const route=String(req.query.route||'');if(!(await auth(req,route)))return out(res,401,{error:'unauthorized'});if(route==='status'&&req.method==='GET')return out(res,200,{active:await active()});if(route==='verify'&&req.method==='POST'){if(!(await active()))return out(res,410,{ok:false,error:'bootstrap_inactive'});const h=String(process.env.ARA_BOOTSTRAP_OTP_HASH||''),exp=Number(process.env.ARA_BOOTSTRAP_OTP_EXP||0),code=String((req.body||{}).code||''),got=crypto.createHash('sha256').update(code).digest('hex');if(!safe(got,h))return out(res,403,{ok:false});await table();const q=await pool.query('INSERT INTO ara_oauth_consumed(kind,issuer,jti,expires_at) VALUES($1,$2,$3,to_timestamp($4)) ON CONFLICT DO NOTHING RETURNING jti',['bootstrap_otp',ISS,h,exp]);return out(res,q.rowCount===1?200:409,{ok:q.rowCount===1})}return out(res,404,{error:'not_found'})}catch(e){console.error('bootstrap',e);return out(res,500,{error:'internal_error'})}};